def find_lcm(a, b):
    """Helper function to compute the least common multiple of two numbers."""
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    return abs(a * b) // gcd(a, b)

def lcm_of_list(numbers):
    """Helper function to compute the least common multiple of a list of numbers."""
    if not numbers:
        return 1
    current_lcm = numbers[0]
    for number in numbers[1:]:
        current_lcm = find_lcm(current_lcm, number)
    return current_lcm

